<script>
 import {isMock} from '../api';
 import RegionState from './RegionState.svelte';
 import {startExecutionPrefs} from '../stores/execution-prefs.svelte';
 import {commitEditorEdit} from '../services/editor.js';
 import EditorTools from './EditorTools.svelte';
 import VersionBar from './VersionBar.svelte';
 import {tasks as taskState} from '../stores/tasks.svelte';
 import {editor as editorState} from '../stores/editor.svelte';
 import ChatPanel from './ChatPanel.svelte';import Resizer from '../ui/Resizer.svelte';import {shell,saveShell,routing,startRouting,navigate} from '../app/shell.svelte';import {editorUrl,libraryUrl} from '../lib/router.ts';import HomePage from './HomePage.svelte';import AssetLibrary from './AssetLibrary.svelte';import {selection} from '../stores/selection.svelte';import {assets as assetStore} from '../stores/assets.svelte';import {historyCommand,trashSelectionCommand} from '../services/commands.js';import {stopCurrentTask} from '../services/workspace.svelte';import {latestRunningRow,stopChat,connectChat} from '../stores/chat.svelte';import {startSelectionContext} from '../stores/selection.svelte';
 import RatioBar from './RatioBar.svelte';import {ratios} from '../lib/ratio.ts';import {chooseRatioCommand,swapRatioCommand} from '../services/commands.js';
 import {installApplicationShortcuts} from '../lib/shortcuts.ts';
 import TaskCenter from './TaskCenter.svelte';import FolderAuthorization from './FolderAuthorization.svelte';
 import Feedback from './Feedback.svelte';
 import TeamBar from './TeamBar.svelte';
 import {layout,updateViewport} from '../layout.svelte';
 import {onMount,tick,untrack} from 'svelte';import {SlidersHorizontal,Crop,RotateCw,Columns2,Upload,FolderOpen,Grid2X2,Plus,ArrowUpRight,Sparkles,Save,Check,X,ChevronDown,PanelRightClose,PanelRightOpen,Download,FlipHorizontal,FlipVertical,RotateCcw} from 'lucide-svelte';
 import {studio,current,asset,assets,scope,initialize,dispose,select,run,save,notify,importImages,dropImages,change,undo,redo,isDirty,thumbnails,clearSelection,liveAssets} from '../studio.svelte';import {api,initialEdit} from '../api';
 import RadialMenu from './RadialMenu.svelte';
 import Canvas from './Canvas.svelte';import Inspector from './Inspector.svelte';import CoverflowHost from './CoverflowHost.svelte';import Library from './Library.svelte';import ExportPanel from './Export.svelte';import SettingsPanel from './Settings.svelte';import Generate from './Generate.svelte';import Assistant from './Assistant.svelte';
 let radial=$state(null),dragOver=$state(false),visited=$state([]),compareBeforeHold=false,compareSplit=50;const compareKeys=new Set();
 onMount(()=>{const stopPrefs=startExecutionPrefs(),stopChatSync=connectChat(),stopContext=startSelectionContext(),stopRouting=startRouting(),shortcuts=installApplicationShortcuts({getContext:()=>({page:studio.mode==='edit'?(studio.view==='canvas'?'editor':studio.view==='grid'?'library':'projects'):studio.mode,busy:!studio.ready||!!studio.busy||studio.paintMenuOpen}),onError:e=>studio.error=e.message,actions:{...Object.fromEntries(ratios.map((ratio,index)=>[`editor.ratio.${index+1}`,()=>chooseRatioCommand(ratio)])),'editor.ratio.swap':swapRatioCommand,'editor.previous':()=>step(-1),'editor.next':()=>step(1),
   'composer.focus':focusComposer,'chat.toggle':toggleChat,'history.undo':()=>historyCommand('undo'),'history.redo':()=>historyCommand('redo'),'task.escape':escapeTask,
   'editor.save':saveNow,'editor.compare':compareHeld,'editor.mask.smaller':()=>editorState.mask.size=Math.max(2,Number(editorState.mask.size)-4),'editor.mask.larger':()=>editorState.mask.size=Math.min(300,Number(editorState.mask.size)+4),'editor.fit':()=>{studio.zoom=1;studio.canvasFit=true;studio.pan={x:0,y:0};},'editor.brush':()=>{shell.chatCollapsed=true;saveShell();studio.paintTool=null;studio.tool='mask';studio.inspectorTab='properties';studio.inspector=true;},'editor.tool.previous':()=>cycleTool(-1),'editor.tool.next':()=>cycleTool(1),
   'library.selectAll':()=>selection.set(assetStore.filteredIds),'library.trash':trashSelectionCommand,'library.open':()=>{const id=selection.selectedIds[0];if(id)navigate(editorUrl(id));}
}});if(location.pathname==='/generate')studio.mode='generate';initialize({lazyThumbnails:true});studio.inspector=window.innerWidth>900;updateViewport();window.addEventListener('resize',updateViewport);return()=>{stopPrefs();stopChatSync();shortcuts.destroy();stopContext();stopRouting();window.removeEventListener('resize',updateViewport);dispose();};});
 $effect(()=>{if(studio.mode==='edit'&&studio.view==='projects')for(const p of studio.projects)thumbnails(p,false,p.assets.slice(0,1).map(a=>a.id));});

 $effect(()=>{if(studio.ready&&['generate','export','assistant'].includes(studio.mode)&&!visited.includes(studio.mode))visited.push(studio.mode);});
 const chatOpen=$derived(studio.ready&&(studio.mode==='edit'&&studio.view!=='projects'||studio.workflowChat===studio.mode)&&!shell.chatCollapsed);
 $effect(()=>{const route=routing.current,ready=studio.ready;if(ready)untrack(()=>{if(route.page==='home')studio.mode='home';else if(route.page==='generate')studio.mode='generate';else if(route.page==='library'){studio.mode='edit';studio.view='grid';}else if(route.page==='settings')studio.mode='settings';else if(route.page==='editor'){const p=studio.projects.find(p=>p.assets.some(a=>a.id===route.assetId));if(p){if(p.id!==studio.pid){studio.pid=p.id;studio.selected=[];}if(studio.aid!==route.assetId)select(route.assetId,true);studio.mode='edit';studio.view='canvas';}}});});
 $effect(()=>{const view=studio.view,page=routing.current.page,ready=studio.ready,mode=studio.mode;if(ready&&mode==='edit'&&view==='grid'&&page==='editor')untrack(()=>navigate(libraryUrl(shell.filter)));});
 $effect(()=>{const id=studio.aid;if(studio.ready&&routing.current.page==='editor'&&studio.mode==='edit'&&id&&id!==routing.current.assetId)untrack(()=>navigate(editorUrl(id),{replace:true}));});
 const modes=[['home','首页'],['edit',"编辑"],['generate',"生成图片"],['export',"导出"],['settings',"设置"]];
 function mode(value){if(studio.busy)return;studio.mode=value;if(value==='home')navigate('/');else if(value==='generate')navigate('/generate');else if(value==='settings')navigate('/settings');else if(value==='edit')navigate(studio.aid?editorUrl(studio.aid):libraryUrl(shell.filter));studio.settingsReturn='';studio.view='canvas';radial=null;}
 let panelVisible=$derived(studio.inspector&&!layout.focus&&studio.mode==='edit'&&studio.view==='canvas');
 function panelOpen(value){return !chatOpen&&panelVisible&&studio.tool===value&&studio.inspectorTab==='adjust';}
 function tool(value,toggle=false){const closing=toggle&&panelOpen(value);shell.chatCollapsed=true;saveShell();
  if(studio.busy)return;
  studio.paintTool=null;studio.picking=false;
  if(closing){studio.inspector=false;return;}
  layout.focus=false;studio.tool=value;studio.mode='edit';studio.view='canvas';studio.inspectorTab='adjust';studio.inspector=true;
 }
 function closeInspector(){studio.inspector=false;document.querySelector(`[data-tool="${studio.tool}"]`)?.focus();}
 function toggleInspector(){if(studio.busy||studio.mode!=='edit'||studio.view!=='canvas')return;if(layout.focus){layout.focus=false;studio.inspector=true;}else studio.inspector=!studio.inspector;}

 async function saveNow(){if(!isDirty())return;await commitEditorEdit();}
 function step(direction){const ids=editorState.coverflowIds??(selection.selectedIds.length?selection.selectedIds:assetStore.filteredIds),i=ids.indexOf(studio.aid);if(ids[i+direction])select(ids[i+direction]);}
 async function focusComposer(){if(studio.mode==='generate'){document.querySelector('.np-page textarea[aria-label="新品套图要求"],.generation-form textarea[aria-label="图片生成要求"]')?.focus();return;}if(studio.mode!=='home'&&(studio.mode!=='edit'||studio.view==='projects'))navigate(libraryUrl(shell.filter));if(studio.mode!=='home'){shell.chatCollapsed=false;saveShell();}await tick();document.querySelector('[data-composer]')?.focus();}
 function toggleChat(){if(['generate','assistant'].includes(studio.mode)){const wasOpen=studio.workflowChat===studio.mode&&!shell.chatCollapsed;studio.workflowChat=studio.mode;shell.chatCollapsed=wasOpen;saveShell();return;}if(studio.mode!=='edit'||studio.view==='projects'){void focusComposer();return;}shell.chatCollapsed=!shell.chatCollapsed;saveShell();}
 function cycleTool(direction){const tools=['adjust','crop','transform'],i=tools.indexOf(studio.tool);tool(tools[(i+direction+tools.length)%tools.length]);}
 function compareHeld(event,phase){if(phase==='press'){if(!compareKeys.size){compareBeforeHold=studio.compare;compareSplit=studio.split;}compareKeys.add(event.code);studio.compare=true;studio.split=100;}else{compareKeys.delete(event.code);if(!compareKeys.size){studio.compare=compareBeforeHold;studio.split=compareSplit;}}}
 async function escapeTask(){if(studio.picking){studio.picking=false;return;}if(radial){closeRadial();return;}const row=latestRunningRow();if(row){await stopChat(row);return;}if(!await stopCurrentTask()&&studio.busy)await api('cancel_job');}

 async function dropped(e){e.preventDefault();dragOver=false;const files=[];async function read(entry){if(entry.isFile){const f=await new Promise((resolve,reject)=>entry.file(resolve,reject));if(f.type.startsWith('image/'))files.push(f);}else if(entry.isDirectory){const reader=entry.createReader();while(true){const children=await new Promise((resolve,reject)=>reader.readEntries(resolve,reject));if(!children.length)break;for(const child of children)await read(child);}}}const entries=[...e.dataTransfer.items].map(i=>i.webkitGetAsEntry?.()).filter(Boolean);if(entries.length){for(const entry of entries)await read(entry);}else files.push(...[...e.dataTransfer.files].filter(f=>f.type.startsWith('image/')));dropImages(files);}
 function closeRadial(){radial=null;studio.paintMenuOpen=false;document.querySelector('.canvas-stage')?.focus({preventScroll:true});}
 function context(e){if(studio.mode!=='edit'||studio.view!=='canvas'||studio.busy||!asset()||!e.target.closest('.canvas-stage'))return;e.preventDefault();studio.picking=false;studio.paintMenuOpen=true;radial={x:e.clientX,y:e.clientY};}
 $effect(()=>{if(studio.mode!=='edit'||studio.view!=='canvas'||studio.busy){radial=null;studio.paintMenuOpen=false;studio.picking=false;}});

</script>
<svelte:window  onblur={()=>{studio.spacePan=false;}}/>
<div class="app complete-app" ondropcapture={()=>dragOver=false} ondragovercapture={e=>{if(e.target.closest?.('.np-page,.composer,.asset-library'))dragOver=false;}} ondragover={e=>{e.preventDefault();if(e.target.closest?.('.np-page,.composer,.asset-library')){dragOver=false;return;}dragOver=true;}} ondragleave={e=>{if(!e.currentTarget.contains(e.relatedTarget))dragOver=false;}} ondrop={dropped} role="application" aria-label="GVPAK STUDIO">
 <header class="app-header" inert={!studio.ready||!!studio.busy}><button class="brand" aria-label="打开项目" onclick={()=>{studio.mode='edit';studio.view='projects';}}><span>GVPAK</span><span class="brand-studio">STUDIO</span></button><button class="project-switch" onclick={()=>{studio.mode='edit';studio.view=studio.view==='projects'?'canvas':'projects';}}><span class="project-square"></span>{current()?.name||"项目"}<ChevronDown size={12}/></button><nav class="mode-tabs" aria-label="工作区">{#each modes as [value,label]}<button class:active={studio.mode===value} onclick={()=>mode(value)} disabled={!!studio.busy}>{label}</button>{/each}</nav><div class="header-actions"><button class="save-button" title="展开或收起对话 · Ctrl+J" onclick={toggleChat} aria-pressed={chatOpen}>对话</button><TaskCenter readSession={true} includeNewProduct={true} onresult={task=>{if(task.type==='new-product')mode('generate');else if(task.type==='operation'){if(task.projectId)studio.pid=task.projectId;studio.selected=task.resultAssetIds||[];shell.filter={folder:'',tag:'',status:'',q:'',sort:''};navigate('/library');}else{studio.processTab='jobs';mode('assistant');}}}/><button class="ai-button" class:active={studio.mode==='assistant'} disabled={!asset()||!!studio.busy} onclick={()=>mode('assistant')}><Sparkles size={15}/>处理图片</button><button class="save-button" title="保存版本 · Ctrl+S" disabled={!asset()||!isDirty()||!!studio.busy} onclick={saveNow}><Save size={15}/><span>保存版本</span></button></div></header>
 {#if isMock}<div class="mock-mode" role="status">模拟模式 · 内存演示，刷新后重置。云处理与输出保存未启用。</div>{/if}
 <FolderAuthorization restore={true}/>
 <div class="project-warning-notice" role="status" hidden={!studio.projectWarnings.length}><span>{studio.projectWarnings.length} 个项目未能加载。</span><button class="text-button" onclick={()=>{studio.mode='settings';studio.view='canvas';}}>查看问题和数据目录</button></div><div class="app-workspace" style:grid-template-columns={studio.mode==='home'?'minmax(0,1fr)':chatOpen?`48px minmax(0,1fr) ${shell.chatWidth}px`:undefined}>{#if studio.mode!=='home'}<nav inert={!studio.ready||!!studio.busy} class="toolrail" aria-label="图片工具"><EditorTools/><button data-tool="adjust" class:chosen={panelOpen('adjust')} onclick={()=>tool('adjust',true)} aria-controls="editor-inspector" aria-expanded={panelOpen('adjust')} title={panelOpen('adjust')?"调色：收起面板":"调色：打开面板"} aria-label="调色"><SlidersHorizontal size={20}/></button><button data-tool="crop" class:chosen={panelOpen('crop')} onclick={()=>tool('crop',true)} aria-controls="editor-inspector" aria-expanded={panelOpen('crop')} title={panelOpen('crop')?"裁切：收起面板":"裁切：打开面板"} aria-label="裁切"><Crop size={20}/></button><button data-tool="transform" class:chosen={panelOpen('transform')} onclick={()=>tool('transform',true)} aria-controls="editor-inspector" aria-expanded={panelOpen('transform')} title={panelOpen('transform')?"旋转与翻转：收起面板":"旋转与翻转：打开面板"} aria-label="旋转与翻转"><RotateCw size={20}/></button><button class:chosen={studio.compare} onclick={()=>{mode('edit');studio.compare=!studio.compare;}} title="对比原图" aria-label="对比原图"><Columns2 size={20}/></button><span class="rail-divider"></span><button onclick={()=>importImages(false)} disabled={!!studio.busy} title="导入图片" aria-label="导入图片"><Upload size={20}/></button><button onclick={()=>importImages(true)} disabled={!!studio.busy} title="导入文件夹" aria-label="导入文件夹"><FolderOpen size={20}/></button><button class:chosen={studio.view==='grid'} onclick={()=>{const next=studio.view==='grid'?'canvas':'grid';mode('edit');studio.view=next;}} title="图片列表" aria-label="图片列表"><Grid2X2 size={20}/></button><div class="rail-bottom"><button onclick={toggleInspector} disabled={studio.mode!=='edit'||studio.view!=='canvas'} title={panelVisible?"隐藏右侧面板":"显示右侧面板"} aria-label="显示或隐藏右侧面板" aria-controls="editor-inspector" aria-expanded={panelVisible}>{#if panelVisible}<PanelRightClose size={19}/>{:else}<PanelRightOpen size={19}/>{/if}</button></div></nav>{/if}
 <main class:editing={studio.mode==='edit'} oncontextmenu={context} role="region" aria-label="工作区内容">
 {#if !studio.ready}<RegionState state={studio.startupState==='error'?'error':'loading'} title={studio.startupState==='error'?'无法打开工作区':'正在打开工作区'} message={studio.startupState==='error'?studio.startupError:'正在读取项目、模型和任务…'} onretry={()=>initialize({lazyThumbnails:true})}/>
 {:else if studio.mode==='home'}<div class="complete-home"><HomePage/></div>
 {:else if studio.view!=='canvas'&&studio.mode==='edit'}{#if studio.view==='projects'}<Library/>{:else}<AssetLibrary/>{/if}
 {:else if studio.mode==='edit'}<div class="editor-canvas"><div class="editor-ratio-strip"><RatioBar disabled={!!studio.busy} onerror={e=>studio.error=e.message}/></div><Canvas/></div><VersionBar/>{#if !layout.focus}<CoverflowHost/>{/if}
 {:else if studio.mode==='settings'}<SettingsPanel/>{/if}
 {#if visited.includes('export')}<div class="workflow-host" hidden={studio.mode!=='export'||!studio.ready}><ExportPanel/></div>{/if}
 {#if visited.includes('generate')}<div class="workflow-host" hidden={studio.mode!=='generate'||!studio.ready}><Generate/></div>{/if}
 {#if visited.includes('assistant')}<div class="workflow-host" hidden={studio.mode!=='assistant'||!studio.ready}><Assistant/></div>{/if}
 </main>{#if chatOpen}<aside class="complete-chat" aria-label="对话栏"><Resizer label="对话栏宽度" bind:value={shell.chatWidth} min={360} max={520} initial={400} direction={-1} onchange={saveShell}/><ChatPanel onshow={row=>{studio.selected=row.resultAssetIds;studio.view='grid';}} onexport={row=>{studio.selected=row.resultAssetIds;studio.batchScope='selected';mode('export');}}/></aside>{/if}{#if studio.ready&&!chatOpen&&studio.inspector&&!layout.focus&&studio.mode==='edit'&&studio.view==='canvas'}<Inspector onclose={closeInspector}/>{/if}</div>
 <footer class="app-footer"><span><i class:working={!!studio.busy}></i>{studio.busy||"就绪"}{#if studio.progress}<b>{studio.progress.done} / {studio.progress.total}</b>{/if}</span><span>{studio.selected.length?`${studio.selected.length} 已勾选`:asset()?"当前图片":"暂无图片"}{#if studio.selected.length}<button class="clear-selection" disabled={!!studio.busy} onclick={clearSelection} aria-label="取消全部勾选">清除</button>{/if}</span><span class="footer-right">{isDirty()?studio.draftStatus:''}{#if isDirty()}<button class="clear-selection" title="恢复到已保存的版本" onclick={()=>change({...asset().edit})}>撤销未保存的修改</button>{/if}<b>GVPAK STUDIO</b></span></footer>
 {#if studio.busy}<div class="busy-pill" role="status"><span class="spinner"></span>{studio.busy}{#if studio.progress}<span>{studio.progress.done}/{studio.progress.total}</span><button onclick={()=>api('cancel_job').catch(e=>studio.error=e.message)}>取消剩余任务</button>{/if}</div>{/if}
 {#if studio.error&&(studio.ready||studio.startupState!=='error')}<div class="error-notice" role="alert"><span>{studio.error}</span><button aria-label="关闭错误提示" onclick={()=>studio.error=''}><X size={15}/></button></div>{/if}



 {#if dragOver}<div class="drop-overlay"><Upload size={32}/><h2>拖入图片以导入</h2></div>{/if}
 {#if radial}<RadialMenu anchor={radial} onclose={closeRadial}/>{/if}
</div>


<TeamBar/>

<Feedback/>

<style>.editor-ratio-strip{display:flex;align-items:center;min-height:40px;padding:4px 12px;box-sizing:border-box;background:var(--bg-elev);border-bottom:1px solid var(--border)}.complete-home{height:100%;overflow:auto;background:var(--bg)}.complete-chat{position:relative;min-width:0;min-height:0;height:100%;border-left:1px solid var(--border);}.complete-chat>:global(.ui-resizer){position:absolute;left:-4px;top:0;bottom:0;z-index:5}.mock-mode{flex-shrink:0;padding:8px 16px;min-height:32px;box-sizing:border-box;color:var(--warning-text);background:var(--warning);font:12px system-ui,sans-serif;border-bottom:1px solid var(--border)}</style>
